internal fun buildGbkDecodeMap(): Map<Int, Char> {
    val map = HashMap<Int, Char>(23940)
    for (seg in GBK_DECODE_TABLE_COMPRESSED.split(';')) {
        if (seg.isEmpty()) continue
        val p = seg.split(',')
        if (p.size != 3) continue
        val code = p[0].toIntOrNull() ?: continue
        val cp = p[1].toIntOrNull() ?: continue
        val len = p[2].toIntOrNull() ?: continue
        for (k in 0 until len) {
            map[code + k] = (cp + k).toChar()
        }
    }
    return map
}
